mapper.select:
SELECT od.product_name AS name, SUM(od.quantity) AS number
FROM order_item od
INNER JOIN purchase_order o ON od.order_id = o.id
WHERE o.order_status IN (3, 4)

    AND o.pay_time >= #{beginTime}


    AND o.pay_time <= #{endTime}


    AND EXISTS (
        SELECT 1 FROM product p WHERE p.id = od.product_id AND p.store_id IN
        #{sid}
    )

GROUP BY od.product_name
ORDER BY number DESC
LIMIT 0, 10

